#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int lech = 0;
    for (int i = 0; i < n; i++) {
        int mong, thuc;
        scanf("%d %d", &mong, &thuc);
        if (mong != thuc) lech++;
    }
    printf("%d\n", lech);
    return 0;
}
